import axios from 'axios';

const API_URL = 'http://localhost:3001/api/chambres';

const chambreService = {
  // Récupérer toutes les chambres
  getAll: async () => {
    try {
      const response = await axios.get(API_URL);
      return response.data;
    } catch (error) {
      console.error('Erreur lors de la récupération des chambres:', error);
      throw error;
    }
  },

  // Récupérer une chambre par son ID
  getById: async (id_chambre) => {
    try {
      const response = await axios.get(`${API_URL}/${id_chambre}`);
      return response.data;
    } catch (error) {
      console.error(`Erreur lors de la récupération de la chambre ${id_chambre}:`, error);
      throw error;
    }
  },

  // Créer une nouvelle chambre
  create: async (chambreData) => {
    try {
      const response = await axios.post(API_URL, chambreData);
      return response.data;
    } catch (error) {
      console.error('Erreur lors de la création de la chambre:', error);
      throw error;
    }
  },

  // Mettre à jour une chambre
  update: async (id_chambre, chambreData) => {
    try {
      const response = await axios.put(`${API_URL}/${id_chambre}`, chambreData);
      return response.data;
    } catch (error) {
      console.error(`Erreur lors de la mise à jour de la chambre ${id_chambre}:`, error);
      throw error;
    }
  },

  // Supprimer une chambre
  delete: async (id_chambre) => {
    try {
      const response = await axios.delete(`${API_URL}/${id_chambre}`);
      return response.data;
    } catch (error) {
      console.error(`Erreur lors de la suppression de la chambre ${id_chambre}:`, error);
      throw error;
    }
  }
};

export default chambreService;
